-- "Ask your agent" (#681 B1; docs/plans/2026-11-27-mcp-oauth.md section 3.1): the
-- agent_request table, a synced root owned by the asker (src/db/sync-tables.ts). Generated by
-- drizzle-kit, then its sync triggers added by hand at the end, as 0052 writes them for every
-- root (drizzle-kit cannot model triggers; test/integration/sync-triggers.spec.ts holds
-- pg_trigger to sync-tables.ts). The tombstone check is recreated to name the new table.
--
-- A new, empty table: no backfill and no data step. The CREATE TRIGGERs take only the new
-- table's lock; the tombstone check's re-add scans sync_tombstone under its ACCESS EXCLUSIVE
-- lock, behind a long writer it gives up after 5 s and the boot fails and is retried (as 0069).
-- Rollback: the previous image never reads the table; dropping it (and re-adding the old
-- tombstone check without 'agent_request') is the inverse, once no request is worth keeping.
SET LOCAL lock_timeout = '5s';
--> statement-breakpoint
CREATE TABLE "agent_request" (
	"id" serial PRIMARY KEY NOT NULL,
	"owner_id" integer NOT NULL,
	"body" text NOT NULL,
	"garment_id" integer,
	"trip_id" integer,
	"option_group_id" integer,
	"status" text DEFAULT 'open' NOT NULL,
	"claimed_by_token_id" integer,
	"claimed_at" timestamp with time zone,
	"answer" text,
	"answered_by_token_id" integer,
	"answered_at" timestamp with time zone,
	"answer_seen_at" timestamp with time zone,
	"withdrawn_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"revision" bigint DEFAULT 0 NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"client_id" uuid,
	CONSTRAINT "agent_request_owner_id_client_id_unique" UNIQUE("owner_id","client_id"),
	CONSTRAINT "agent_request_status_check" CHECK ("agent_request"."status" in ('open', 'claimed', 'answered', 'withdrawn')),
	CONSTRAINT "agent_request_body_check" CHECK (length(trim("agent_request"."body")) > 0 and char_length("agent_request"."body") <= 500),
	CONSTRAINT "agent_request_answer_check" CHECK ("agent_request"."answer" is null or (length(trim("agent_request"."answer")) > 0 and char_length("agent_request"."answer") <= 1000)),
	CONSTRAINT "agent_request_one_subject_check" CHECK (num_nonnulls("agent_request"."garment_id", "agent_request"."trip_id", "agent_request"."option_group_id") <= 1),
	CONSTRAINT "agent_request_state_check" CHECK (("agent_request"."status" <> 'claimed' or "agent_request"."claimed_at" is not null) and ("agent_request"."status" <> 'answered' or ("agent_request"."answer" is not null and "agent_request"."answered_at" is not null)) and ("agent_request"."status" <> 'withdrawn' or "agent_request"."withdrawn_at" is not null) and ("agent_request"."answer_seen_at" is null or "agent_request"."status" = 'answered'))
);
--> statement-breakpoint
